const e = $input.first().json;
const pedido = $('Desde el agente').first().json;
if (!e.escalation_id) {
  return [{ json: { avisar: false, estado: 'NO_ESCALADO', motivo: e.detail || e, siguiente_paso: 'Revisar la solicitud; no se notificó al dueño.' } }];
}
const etiquetas = { APROBADA: 'Aprobar', RECHAZADA: 'Rechazar', OFRECER_PARCIAL: 'Ofrecer entrega parcial',
  EVALUAR_REPOSICION: 'Evaluar reposición', DESCARTAR: 'Descartar' };
const opciones = e.tipo === 'DESCUENTO' ? ['APROBADA', 'RECHAZADA'] : ['OFRECER_PARCIAL', 'EVALUAR_REPOSICION', 'DESCARTAR'];
const base = `http://localhost:5678/form/decision-dueno?escalation_id=${e.escalation_id}`;
// Un enlace por decisión: el formulario abre con ESC y decisión ya marcados; el dueño confirma con un clic.
// No se registra con solo abrir el enlace: los lectores de correo abren enlaces automáticamente.
const enlaces = Object.fromEntries(opciones.map(o => [o, `${base}&decision=${o}`]));
const esc = s => String(s ?? '—').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const que = e.tipo === 'DESCUENTO' ? 'Descuento mayor al 5 % (requiere su aprobación)' : 'Falta stock (decida cómo atender)';
const botones = opciones.map((o, i) => `<a href="${enlaces[o]}" style="display:inline-block;margin:4px 6px 4px 0;padding:10px 16px;border-radius:6px;text-decoration:none;color:#fff;background:${i === 0 ? '#1a7f37' : (o === 'RECHAZADA' || o === 'DESCARTAR' ? '#b42318' : '#475467')}">${etiquetas[o]}</a>`).join('');
const fila = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#475467">${k}</td><td style="padding:4px 0"><b>${esc(v)}</b></td></tr>`;
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#101828;max-width:560px">
<h2 style="margin:0 0 8px">${que}</h2>
<p style="margin:0 0 12px">${esc(pedido.resumen)}</p>
<table>${fila('Cotización', `${e.quotation_id} v${e.quotation_version}`)}${fila('Total verificado en Odoo', `S/ ${e.total}`)}
${fila('Escalamiento', e.escalation_id)}${fila('Solicitud', e.request_id)}${e.signal_id ? fila('Señal de reposición', e.signal_id) : ''}
${fila('Responder antes de', e.plazo_hasta)}</table>
<p style="margin:16px 0 4px">Elija una opción (se abre una confirmación de un clic):</p>${botones}
<p style="margin:16px 0 0;color:#667085;font-size:12px">Agente SIE · datos de demostración. Ninguna opción crea pedidos ni reservas en Odoo. Si no responde en 10 minutos, la oportunidad queda en seguimiento.</p></div>`;
return [{ json: {
  avisar: true, estado: 'ESPERANDO_DECISION_DEL_DUENO', escalation_id: e.escalation_id, tipo: e.tipo,
  destinatario: e.destinatario, signal_id: e.signal_id, aprobacion_aplicaria_a_version: e.version_aprobacion,
  total_verificado: e.total, plazo_hasta: e.plazo_hasta, enlaces, html,
  asunto: `[MYS] ${e.tipo === 'DESCUENTO' ? 'Aprobar descuento' : 'Falta stock'}: ${e.quotation_id} v${e.quotation_version} · S/ ${e.total} (${e.escalation_id})`
} }];

const a = $('Preparar aviso').first().json;
if (!a.avisar) { const { avisar, ...resto } = a; return [{ json: resto }]; }
let correo = { enviado: false, detalle: 'no se intentó' };
try {
  const r = $('Correo al dueño').first().json;
  correo = r.error ? { enviado: false, detalle: String(r.error.message || r.error).slice(0, 160) } : { enviado: true };
} catch (err) {}
const salida = {
  estado: a.estado, escalation_id: a.escalation_id, tipo: a.tipo, signal_id: a.signal_id,
  aprobacion_aplicaria_a_version: a.aprobacion_aplicaria_a_version, total_verificado: a.total_verificado, plazo_hasta: a.plazo_hasta,
  aviso_al_dueno: correo.enviado ? 'Correo enviado automáticamente al dueño con los botones de decisión.'
    : `No se pudo enviar el correo (${correo.detalle}). Reenvíe al dueño estos enlaces.`,
  nota: 'Si no hay respuesta en 10 minutos: sin decisión, la oportunidad queda en seguimiento.'
};
if (!correo.enviado) salida.enlaces_para_el_dueno = a.enlaces;
return [{ json: salida }];
